def is_mirror(label):
    i, j = 0, len(label) - 1
    while i < j:
        if not label[i].isalnum():
            i += 1
        elif not label[j].isalnum():
            j -= 1
        elif label[i].lower() != label[j].lower():
            return False
        else:
            i += 1
            j -= 1
    return True

