function is_mirror(label) {
  const ok = (c) => /[a-z0-9]/i.test(c);
  let i = 0;
  let j = label.length - 1;
  while (i < j) {
    if (!ok(label[i])) i++;
    else if (!ok(label[j])) j--;
    else if (label[i].toLowerCase() !== label[j].toLowerCase()) return false;
    else {
      i++;
      j--;
    }
  }
  return true;
}

