class Solution {
    public boolean isMirror(String label) {
        int i = 0, j = label.length() - 1;
        while (i < j) {
            char a = label.charAt(i), b = label.charAt(j);
            if (!Character.isLetterOrDigit(a)) {
                i++;
            } else if (!Character.isLetterOrDigit(b)) {
                j--;
            } else if (Character.toLowerCase(a) != Character.toLowerCase(b)) {
                return false;
            } else {
                i++;
                j--;
            }
        }
        return true;
    }
}

